INSERT INTO books (id, titulo, autor, publicacion, genero, isbn, valoracion, visible, precio_cop, stock, idioma, formato, descripcion) VALUES (180, 'The Vegetarian', 'Han Kang', 2007, 'Ficción', '9781000000180', 1, 1, 40000, 99, 'Inglés', 'Digital', 'An ordinary Korean woman decides to stop eating meat after a disturbing dream, triggering devastating consequences within her family and society.');
INSERT INTO books (id, titulo, autor, publicacion, genero, isbn, valoracion, visible, precio_cop, stock, idioma, formato, descripcion) VALUES (181, 'Donde los árboles cantan', 'Laura Gallego', 2011, 'Fantasía', '9781000000181', 2, 1, 42000, 18, 'Español', 'Físico', 'En un reino medieval de fantasía, Naya debe adentrarse en el bosque encantado donde los espíritus de los muertos hablan a través de los árboles.');
INSERT INTO books (id, titulo, autor, publicacion, genero, isbn, valoracion, visible, precio_cop, stock, idioma, formato, descripcion) VALUES (182, 'La canción de Aquiles', 'Madeline Miller', 2011, 'Ficción', '9781000000182', 3, 1, 46000, 21, 'Español', 'Físico', 'Desde la perspectiva de Patroclo, la historia de amor y guerra entre él y Aquiles durante la legendaria guerra de Troya, contada con sublime belleza.');
