INSERT INTO books (id, titulo, autor, publicacion, genero, isbn, valoracion, visible, precio_cop, stock, idioma, formato, descripcion) VALUES (184, 'Klara et le Soleil', 'Kazuo Ishiguro', 2021, 'Ciencia Ficción', '9781000000184', 5, 1, 47000, 11, 'Francés', 'Físico', 'Klara, une Amie Artificielle, observe le monde depuis la vitrine d''un magasin en attendant qu''une famille l''achète, portant un regard unique sur l''humanité.');
